entries[13517] = { ["name"] = "Recipe: Alchemist's Stone", ["text"] = "Binds when picked up\nRequires Alchemy (350)\nRequires The Sha'tar\n- Revered\nUse: Teaches you how to make an Alchemist's Stone.\nSell Price: 2\nAlchemist's Stone\nBinds when picked up\nUnique\nTrinket\n+15 Strength\n+15 Agility\n+15 Stamina\n+15 Intellect\n+15 Spirit\nRequires Alchemy (350)\nEquip: Increases the effect that healing and mana potions have on the wearer by 40%. This effect does not stack.\nSell Price: 2 50\nRequires Philosopher's Stone , Earthstorm Diamond , Skyfire Diamond , Fel Lotus (2), Primal Might (5)" }
entries[13518] = { ["name"] = "Recipe: Potion of Petrification", ["text"] = "Requires Alchemy (300)\nUse: Teaches you how to make a Potion of Petrification.\nSell Price: 1\nPotion of Petrification\nRequires Level 50\nUse: You turn to stone, absorbing up to 6000 total damage, but you are unable to move, attack, or cast spells. Lasts 30 sec. (1 Min Cooldown)\nSell Price: 12 50\nRequires Stonescale Oil (7), Crystal Vial" }
entries[13519] = { ["name"] = "Recipe: Flask of the Titans", ["text"] = "Requires Alchemy (300)\nUse: Teaches you how to make a Flask of the Titans.\nSell Price: 1\nFlask of the Titans\nRequires Level 50\nUse: Increases the player's maximum health by 400 for 1 hour. Counts as both a Battle and Guardian elixir. This effect persists through death. (3 Sec Cooldown)\nSell Price: 12 50\nRequires Gromsblood (7), Stonescale Oil (3), Black Lotus , Crystal Vial" }
entries[13520] = { ["name"] = "Recipe: Flask of Distilled Wisdom", ["text"] = "Requires Alchemy (300)\nUse: Teaches you how to make a Flask of Distilled Wisdom.\nSell Price: 1\nFlask of Distilled Wisdom\nRequires Level 50\nUse: Increases Intellect by 65 for 1 hour. Counts as both a Battle and Guardian elixir. This effect persists through death. (3 Sec Cooldown)\nSell Price: 12 50\nRequires Dreamfoil (7), Icecap (3), Black Lotus , Crystal Vial" }
entries[13521] = { ["name"] = "Recipe: Flask of Supreme Power", ["text"] = "Requires Alchemy (300)\nUse: Teaches you how to make a Flask of Supreme Power.\nSell Price: 1\nFlask of Supreme Power\nRequires Level 50\nUse: Increases spell power by 70 for 1 hour. Counts as both a Battle and Guardian elixir. This effect persists through death. (3 Sec Cooldown)\nSell Price: 12 50\nRequires Dreamfoil (7), Mountain Silversage (3), Black Lotus , Crystal Vial" }
entries[13522] = { ["name"] = "Recipe: Flask of Chromatic Resistance", ["text"] = "Requires Alchemy (300)\nUse: Teaches you how to make a Flask of Chromatic Resistance.\nSell Price: 1\nFlask of Chromatic Resistance\nRequires Level 50\nUse: Increases resistance to all schools of magic by 25 for 1 hour. Counts as both a Battle and Guardian elixir. This effect persists through death. (3 Sec Cooldown)\nSell Price: 12 50\nRequires Icecap (7), Mountain Silversage (3), Black Lotus , Crystal Vial" }
